#requires -Version 5.1
[CmdletBinding()]
param([string]$ProjectRoot = (Get-Location).Path)

$ErrorActionPreference = "Stop"
$root = [IO.Path]::GetFullPath($ProjectRoot)
if (-not (Test-Path -LiteralPath (Join-Path $root "project.godot") -PathType Leaf)) {
    throw "project.godot nao encontrado. Execute na raiz do projeto."
}

$files = @(
    @{ Relative = "scripts\hit_music_r7\selector.gd"; Data = "" },
    @{ Relative = "scripts\hit_music_r7\stage_v9.gd"; Data = "" }
)

$backupRoot = Join-Path $root ("backup-r16-fade-" + (Get-Date -Format "yyyyMMdd-HHmmss"))
New-Item -ItemType Directory -Path $backupRoot -Force | Out-Null
foreach ($item in $files) {
    $target = Join-Path $root $item.Relative
    if (-not (Test-Path -LiteralPath $target -PathType Leaf)) {
        throw "Arquivo ausente: $($item.Relative)"
    }
    $backup = Join-Path $backupRoot $item.Relative
    New-Item -ItemType Directory -Path (Split-Path -Parent $backup) -Force | Out-Null
    Copy-Item -LiteralPath $target -Destination $backup -Force
}

try {
    foreach ($item in $files) {
        [IO.File]::WriteAllBytes((Join-Path $root $item.Relative), [Convert]::FromBase64String($item.Data))
    }
}
catch {
    foreach ($item in $files) {
        $backup = Join-Path $backupRoot $item.Relative
        if (Test-Path -LiteralPath $backup) {
            Copy-Item -LiteralPath $backup -Destination (Join-Path $root $item.Relative) -Force
        }
    }
    throw "Falha ao atualizar; os arquivos anteriores foram restaurados. $($_.Exception.Message)"
}

Write-Host ""
Write-Host "HIT MUSIC R16 FADE LIMPO aplicado." -ForegroundColor Green
Write-Host "Backup: $backupRoot" -ForegroundColor Yellow
Write-Host ""
Write-Host " - nenhuma mascara ou desenho sobre a tela"
Write-Host " - saida suave nos elementos existentes"
Write-Host " - painel de dificuldade entra com fade"
Write-Host " - previews de video e musica da R14 preservados"

